class _Customer:
    name: str


def _charge(amount_cents: int) -> Charge:
    return Charge(
        id=1,
        subscription_id=1,
        amount_cents=amount_cents,
        idempotency_key="evt_1",
        period_start=PERIOD_START,
        period_end=PERIOD_END,
    )


def _gift_card(amount_cents: int, code: str = "ABCD1234EFGH") -> GiftCard:
    return GiftCard(
        id=1,
        customer_id=1,
        code=code,
        amount_cents=amount_cents,
        balance_cents=amount_cents,
        funded_at=FUNDED_AT,
        expires_at=EXPIRES_AT,
    )


def test_payment_failed_returns_a_subject() -> None:
    subject, _ = payment_failed(_Customer(name="Ada Lovelace"), _charge(1999))

